function clamp01(value: number): number {
  return Math.min(1.0, Math.max(0.0, value));
}

function readFrame(frameIndex: number, channel: number): number {
  const index = frameIndex * CHANNEL_COUNT + channel;
  return EUROPA_TECNOSINE_VALUES[index] * INV_VALUE_SCALE;
}

export function sampleEuropaTecnosine(timeSeconds: number): vec4 {
  const t = Math.min(EUROPA_TECNOSINE_DURATION, Math.max(0.0, timeSeconds));
  const position = t * EUROPA_TECNOSINE_SAMPLE_RATE;
  const i0 = Math.min(EUROPA_TECNOSINE_FRAME_COUNT - 1, Math.max(0, Math.floor(position)));
  const i1 = Math.min(EUROPA_TECNOSINE_FRAME_COUNT - 1, i0 + 1);
  const u = clamp01(position - i0);

  const c0 = readFrame(i0, 0) + (readFrame(i1, 0) - readFrame(i0, 0)) * u;
  const c1 = readFrame(i0, 1) + (readFrame(i1, 1) - readFrame(i0, 1)) * u;
  const c2 = readFrame(i0, 2) + (readFrame(i1, 2) - readFrame(i0, 2)) * u;
  const c3 = readFrame(i0, 3) + (readFrame(i1, 3) - readFrame(i0, 3)) * u;
  return new vec4(c0, c1, c2, c3);
}
